// ---- Place the two strategy sections in their teaching positions ----
(function placeStrategySections() {
  const workedSec = document.getElementById('revealBtn').closest('section');
  const weDoSec = document.getElementById('weDoGrid').closest('section');
  const checkSec = document.getElementById('checkpointGrid').closest('section');
  const faded = document.getElementById('fadedSection');
  const hinge = document.getElementById('hingeSection');
  workedSec.parentNode.insertBefore(faded, workedSec.nextSibling); // Faded examples follow the I Do
  checkSec.parentNode.insertBefore(hinge, checkSec);                // Hinge question opens the You Do
  // Topic-specific wording for the frame's generic notes
  const tip = weDoSec.querySelector('.parts-instructions');
  if (tip) tip.innerHTML = '💡 <strong>Why we do it this way:</strong> name the <strong>actual</strong> value first, because it is the exact value you divide by. Notice the attendance error and the catering-budget error came out the same: when cost per head is fixed, the money error grows in proportion to the crowd error.';
  const matchDesc = document.getElementById('matchArea').closest('section').querySelector('.sec-desc');
  if (matchDesc) matchDesc.textContent = 'Click a measurement or question, then click its partner. There are five matching pairs in the grid below.';
  const d1 = document.querySelector('#tier1-body .sec-desc');
  if (d1) d1.innerHTML = 'Bounds and percentage errors. Type numbers only: no units, $ or % sign, e.g. <code>7.5</code> or <code>20</code>.';
  const d2 = document.querySelector('#tier2-body .sec-desc');
  if (d2) d2.innerHTML = 'Finer precisions, rounding to one decimal place, and bounds that combine. Type numbers only.';
  const d3 = document.querySelector('#tier3-body .sec-desc');
  if (d3) d3.innerHTML = 'Multi-step problems with money, crowds and building jobs. Type numbers only: no units, $ or % sign.';
})();

// ---- Faded Worked Examples kit (blanks marked with the frame's answerMatches) ----
function checkFaded(exId) {
  const card = document.querySelector('[data-faded-id="' + exId + '"]');
  const blanks = card.querySelectorAll('.faded-blank');
  let allCorrect = true, attempted = 0;
  blanks.forEach(b => {
    b.classList.remove('correct', 'incorrect');
    if (b.value.trim() === '') return;
    attempted++;
    if (answerMatches(b.value, b.dataset.expected)) {
      b.classList.add('correct');
    } else {
      b.classList.add('incorrect');
      allCorrect = false;
    }
  });
  const status = document.getElementById('status-' + exId);
  if (attempted === 0) {
    status.textContent = 'Fill in the blanks first.';
  } else if (attempted < blanks.length) {
    status.textContent = attempted + '/' + blanks.length + ' attempted: keep going.';
  } else if (allCorrect) {
    status.textContent = '✓ All correct.';
  } else {
    status.textContent = '✗ Some incorrect: halve the precision, then subtract and add.';
  }
}
function revealFaded(exId) {
  const card = document.querySelector('[data-faded-id="' + exId + '"]');
  card.querySelectorAll('.faded-blank').forEach(b => {
    b.value = b.dataset.expected;
    b.classList.add('correct');
  });
  document.getElementById('status-' + exId).textContent = 'Answer shown.';
}

// ---- Hinge Question kit ----
function pickHingeOption(btn) {
  if (btn.classList.contains('dimmed')) return;
  const isCorrect = btn.dataset.correct === 'true';
  btn.classList.add('selected', isCorrect ? 'correct' : 'incorrect');
  document.querySelectorAll('.hinge-opt').forEach(o => { if (o !== btn) o.classList.add('dimmed'); });
  document.querySelectorAll('.hinge-feedback').forEach(f => f.classList.remove('visible'));
  const fbId = btn.dataset.feedbackId;
  if (fbId) document.getElementById(fbId).classList.add('visible');
}
function resetHinge() {
  document.querySelectorAll('.hinge-opt').forEach(o => o.classList.remove('selected', 'correct', 'incorrect', 'dimmed'));
  document.querySelectorAll('.hinge-feedback').forEach(f => f.classList.remove('visible'));
}
